const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];let scene='magazine',sound=true,stream,photo=null,selected=0,color='#202127',track=$('#soundtrack'),trackStart=0,trackEnd=24,journeyTime=0,musicMuted=false;
function stopCamera(){window.studio?.stopCamera()}
function setSound(v){sound=v;musicMuted=!v;$('#sound').textContent=v?'Musique activée ♫':'Musique désactivée ♩';$('#sound').setAttribute('aria-pressed',v);if(track)track.muted=!v}
function stopMusic(){if(track){track.pause();track.volume=.55}}
function playMusic(at=0){if(!track||musicMuted)return;try{track.currentTime=Math.max(0,Math.min(23.8,at))}catch{}track.volume=.55;track.muted=false;track.play().catch(()=>{sound=false;musicMuted=true;$('#sound').textContent='Activer le son ♫';$('#sound').setAttribute('aria-pressed','false')})}

function show(id){document.body.classList.toggle('readingMagazine',id==='magazine');window.dispatchEvent(new CustomEvent('siteview',{detail:id}));stopCamera();stopMusic();scene=id;$$('.screen').forEach(e=>e.classList.toggle('active',e.id===id));if(id==='room'){window.experience?.skip();window.scrollTo(0,0)}else window.experience?.reset()}
async function start(withSound){if(!window.experience){$('#loadingStatus').textContent='Préparation du voyage…';return}stopCamera();journeyTime=0;setSound(withSound&&!!track);if(withSound)playMusic(0);await Promise.race([window.experience.ready,new Promise(resolve=>setTimeout(resolve,4500))]);$$('.screen').forEach(e=>e.classList.remove('active'));scene='journey';window.experience.start();window.scrollTo(0,0)}
$('#sound').onclick=()=>{setSound(!sound);if(track&&sound&&!['landing','room','mirror'].includes(scene))playMusic(journeyTime);};$('#start').onclick=()=>start(true);$('#silentStart').onclick=()=>start(false);$('#skip').onclick=()=>{if(['runway','curtain','mirror','room'].includes(scene))show('room');else openRunway()};$('#directRunway').onclick=openRunway;$('#mirrorNav').onclick=()=>show('room');$('#replay').onclick=()=>show('landing');$('#home').onclick=e=>{e.preventDefault();show('magazine')};$('#aboutBtn').onclick=()=>$('#about').showModal();$('#closeAbout').onclick=()=>$('#about').close();
function openRunway(){stopCamera();stopMusic();journeyTime=9;if(!musicMuted)playMusic(9);$$('.screen').forEach(e=>e.classList.remove('active'));scene='runway';window.experience?.runway();window.scrollTo(0,0)}
const phaseText={earth:['LA TERRE','Une invitation à Paris.'],france:['LA FRANCE','La France, puis Paris.'],paris:['PARIS FASHION WEEK · IMMERSION','Au cœur de Paris.'],runway:['LA PASSERELLE','À vous d’entrer en scène.'],curtain:['DERRIÈRE LE RIDEAU','Le défilé continue en coulisses.'],mirror:['LE MIROIR','Votre reflet, votre style.']};window.addEventListener('journeyphase',e=>{let p=e.detail;scene=p;$('#skip').textContent=['runway','curtain','mirror'].includes(p)?'Aller au miroir ↗':'Ouvrir le défilé ↗';$('#phaseLabel').textContent=phaseText[p][0];$('#phaseTitle').textContent=phaseText[p][1];$('#journeyHint').textContent=p==='runway'?'UNE PASSERELLE LIBRE · LE PUBLIC SUR LES CÔTÉS':'TERRE → FRANCE → PARIS → DÉFILÉ → MIROIR'});window.addEventListener('journeytick',e=>{journeyTime=e.detail;if(track&&e.detail>22)track.volume=.55*Math.max(0,(24-e.detail)/2)});window.addEventListener('journeyend',()=>{$$('.screen').forEach(e=>e.classList.toggle('active',e.id==='room'));scene='room';stopMusic()});window.addEventListener('experienceready',()=>{$('#loadingStatus').textContent='Prêt · France → Paris → votre défilé.'});
window.addEventListener('pagehide',stopCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden){stopCamera();if(track)track.pause()}else if(sound&&!['landing','room','mirror'].includes(scene))playMusic(journeyTime)});
window.siteShow=show;$('#magazineNav').onclick=()=>show('magazine');
